window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-832a10774c9c08c5"]={"versions": [{"id": "FIG-832a10774c9c08c5", "releases": ["R4.1.3", "R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Beispielhafte tabellarische Darstellung einer Rückverfolgbarkeitsmatrix (Trace Table) gemäß AUTOSAR-Standardisierungstemplate (TPS Standardization Template). Das Schaubild visualisiert das Zusammenspiel zwischen übergeordneten Anforderungen und spezifizierten Software-Anforderungen auf Modulebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Tabellarische Datenstruktur bestehend aus drei Zeilen und drei Spalten sowie einer Fortsetzungszeile (<code>...</code>):</p>\n<ul class=\"fig-list\">\n<li>Spalte 1: Anforderungs-Identifikatoren der Anforderungsebene (<code>[RS_CANIF_001]</code>, <code>[RS_CANIF_002]</code>, <code>[RS_CANIF_003]</code>).</li>\n<li>Spalte 2: Titel bzw. Beschreibung der jeweiligen Anforderung (<code>Requirement title ...</code>).</li>\n<li>Spalte 3: Zugeordnete Spezifikationselemente der Software-Spezifikation (<code>[SWS_CANIF_0434]</code>, <code>[SWS_CANIF_0435]</code>, <code>[SWS_CANIF_0436]</code>), blau hervorgehoben als Hyperlink- bzw. Spezifikationsverweise.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Mapping-Schema ohne sequentiellen Ablauf. Dargestellt ist eine 1:1-Zuordnungsrelation zur Nachweisführung der Anforderungsabdeckung von <code>RS_CANIF</code>-Elementen zu <code>SWS_CANIF</code>-Elementen im Rahmen des Spezifikations-Workflows.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Exemplarische Vorlage zur Umsetzung von Traceability-Tabellen im Dokumentationsframework von AUTOSAR. Die Spezifikationskennzeichner dienen Autoren und Werkzeugentwicklern als Referenzmuster für die Verknüpfung von Requirements (<code>RS</code>) und Software-Spezifikationen (<code>SWS</code>) unter Verwendung standardisierter Tags.</p>"}, {"id": "FIG-5e89cb0827f7777f", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Beispielhafte tabellarische Darstellung einer Rückverfolgbarkeitsmatrix (Trace Table) gemäß AUTOSAR-Standardisierungstemplate (TPS Standardization Template). Das Schaubild visualisiert das Zusammenspiel zwischen übergeordneten Anforderungen und spezifizierten Software-Anforderungen auf Modulebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Tabellarische Datenstruktur bestehend aus drei Zeilen und drei Spalten sowie einer Fortsetzungszeile (<code>...</code>):</p>\n<ul class=\"fig-list\">\n<li>Spalte 1: Anforderungs-Identifikatoren der Anforderungsebene (<code>[RS_CANIF_001]</code>, <code>[RS_CANIF_002]</code>, <code>[RS_CANIF_003]</code>).</li>\n<li>Spalte 2: Titel bzw. Beschreibung der jeweiligen Anforderung (<code>Requirement title ...</code>).</li>\n<li>Spalte 3: Zugeordnete Spezifikationselemente der Software-Spezifikation (<code>[SWS_CANIF_0434]</code>, <code>[SWS_CANIF_0435]</code>, <code>[SWS_CANIF_0436]</code>), blau hervorgehoben als Hyperlink- bzw. Spezifikationsverweise.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Mapping-Schema ohne sequentiellen Ablauf. Dargestellt ist eine 1:1-Zuordnungsrelation zur Nachweisführung der Anforderungsabdeckung von <code>RS_CANIF</code>-Elementen zu <code>SWS_CANIF</code>-Elementen im Rahmen des Spezifikations-Workflows.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Exemplarische Vorlage zur Umsetzung von Traceability-Tabellen im Dokumentationsframework von AUTOSAR. Die Spezifikationskennzeichner dienen Autoren und Werkzeugentwicklern als Referenzmuster für die Verknüpfung von Requirements (<code>RS</code>) und Software-Spezifikationen (<code>SWS</code>) unter Verwendung standardisierter Tags.</p>"}], "trans": [{"from": "FIG-832a10774c9c08c5", "to": "FIG-5e89cb0827f7777f", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
